ctx.lineTo(-3*s+run,7*s);
ctx.moveTo(2*s,1*s);
ctx.lineTo(3*s-run,7*s);
ctx.stroke();
ctx.strokeStyle='#18221f';
ctx.lineWidth=2*s;
ctx.beginPath();
ctx.moveTo(-3*s+run,7*s);
ctx.lineTo(-5*s+run,8*s);
ctx.moveTo(3*s-run,7*s);
ctx.lineTo(5*s-run,8*s);
ctx.stroke();

// body and jersey
ctx.fillStyle=isHome?teams[home][2]:teams[away][2];
ctx.beginPath();
ctx.ellipse(0,-1*s,6*s,7*s,0,0,Math.PI*2);
ctx.fill();
ctx.strokeStyle='rgba(255,255,255,.34)';
ctx.lineWidth=.8*s;
ctx.beginPath();
ctx.moveTo(-4*s,-5*s);
ctx.lineTo(4*s,-5*s);
ctx.stroke();

// arms
ctx.strokeStyle=isHome?teams[home][2]:teams[away][2];
ctx.lineWidth=3*s;
ctx.beginPath();
ctx.moveTo(-5*s,-3*s);
ctx.lineTo(-8*s,1*s);
ctx.moveTo(5*s,-3*s);
ctx.lineTo(8*s,0);
ctx.stroke();

// helmet
ctx.fillStyle='#e8e4d7';
ctx.beginPath();
ctx.arc(0,-8*s,4.4*s,Math.PI,Math.PI*2);
ctx.lineTo(4.4*s,-7*s);
ctx.quadraticCurveTo(0,-3*s,-4.4*s,-7*s);
ctx.fill();
ctx.strokeStyle='#202a26';
ctx.lineWidth=1*s;
ctx.beginPath();
ctx.moveTo(0,-8*s);
ctx.lineTo(4.7*s,-7*s);
ctx.stroke();

if(p.carrier){ctx.fillStyle='#9e4f29';
ctx.beginPath();
ctx.ellipse(7*s,-1*s,4*s,2.1*s,-.5,0,Math.PI*2);
ctx.fill();
ctx.strokeStyle='#e0a271';
ctx.lineWidth=.6*s;
ctx.beginPath();
ctx.moveTo(5*s,-1*s);
ctx.lineTo(9*s,-1*s);
ctx.stroke()}
ctx.restore()}
let carrier=null;

function ballCarrier(){return carrier}

function draw(time){ctx.setTransform(dpr,0,0,dpr,0,0);
drawStadium(time);
for(const p of players.slice().sort((a,b)=>a.y-b.y))playerDraw(p,time);
if(passObj){const p=fieldPoint(passObj.x,passObj.y),arc=Math.sin(passObj.t*Math.PI)*35;
ctx.fillStyle='#7d3b20';
ctx.beginPath();
ctx.ellipse(p.x,p.y-arc,7,3,-.4,0,Math.PI*2);
ctx.fill();
ctx.strokeStyle='#edc398';
ctx.lineWidth=1;
ctx.beginPath();
ctx.moveTo(p.x-3,p.y-arc);
ctx.lineTo(p.x+3,p.y-arc);
ctx.stroke()}}

function resetFormation(){players=[];
carrier={x:50,y:76,team:0,phase:0,carrier:true,angle:0};
players.push(carrier);

// offensive line
for(let i=0;
i<5;
i++)players.push({x:38+i*6,y:78,team:0,phase:i,angle:0});

// receivers & back
players.push({x:16,y:70,team:0,phase:6,route:'left'});
players.push({x:84,y:68,team:0,phase:3,route:'right'});
players.push({x:30,y:68,team:0,phase:5,route:'left'});
players.push({x:70,y:68,team:0,phase:4,route:'right'});
players.push({x:50,y:83,team:0,phase:7,route:'back'});

// defense 11, spread levels
for(let i=0;
i<4;
i++)players.push({x:34+i*10,y:67+(i%2)*2,team:1,phase:i,angle:0});

for(let i=0;
i<3;
i++)players.push({x:30+i*20,y:53,team:1,phase:i+5,angle:0});

for(let i=0;
i<4;
i++)players.push({x:18+i*21,y:39+(i%2)*5,team:1,phase:i+8,angle:0});

ball={x:50,y:76};
passObj=null;
}

function initGame(){home=+$('#homeSelect').value;
away=+$('#awaySelect').value;
score=[0,0];
clock=240;
quarter=1;
down=1;
toGo=10;
spot=25;
playNum=0;
playing=true;
menu=false;
$('#menu').style.display='none';
$('#scoreboard').style.display='flex';
$('#drive').style.display='block';
$('#hint').style.display='block';
$('#status').style.display='block';
$('#mobileControls').style.display=window.innerWidth<=680?'flex':'none';
$('#gameover').classList.remove('show');
$('#homeLogo').textContent=short(home);
$('#awayLogo').textContent=short(away);
$('#homeAbbr').textContent=teams[home][0].toUpperCase();
$('#awayAbbr').textContent=teams[away][0].toUpperCase();
resetFormation();
updateHUD();
showCall('READY, SET…');
}

function updateHUD(){$('#homeScore').textContent=score[0];
$('#awayScore').textContent=score[1];
const seconds=Math.max(0,Math.ceil(clock));
$('#clock').textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;
$('#clockInfo').textContent=`${['','1ST','2ND','3RD','4TH'][quarter]} QUARTER`;
$('#drive').textContent=`${['','1ST','2ND','3RD','4TH'][down]} & ${toGo} · BALL ON ${Math.round(spot)}`;
}

function showCall(text,accent=''){const c=$('#callout');
c.innerHTML=accent?`${text} <span>${accent}</span>`:text;
c.style.display='block';
callTimer=1.5;
}

function toast(t){const e=$('#toast');
e.textContent=t;
e.classList.add('show');
clearTimeout(toastTimer);
toastTimer=setTimeout(()=>e.classList.remove('show'),1500)}

function endPlay(kind){if(!playing)return;
playing=false;
carrier.carrier=false;
if(kind==='td'){score[0]+=7;
showCall('TOUCHDOWN','+7');
toast('SIX POINTS! EXTRA POINT GOOD');
setTimeout(()=>{spot=25;
down=1;
toGo=10;
resetFormation();
playing=true;
updateHUD()},1700);
}
else if(kind==='tackle'){const gain=Math.max(0,Math.round((76-ball.y)*.85));
spot=clamp(spot+gain,1,99);
if(gain>=toGo){down=1;
toGo=10;
showCall('FIRST DOWN','+'+gain)}else{down++;
toGo=Math.max(1,toGo-gain);
showCall('TACKLED',gain?`${gain} YDS`:'NO GAIN')}if(down>4){down=1;
toGo=10;
spot=25;
showCall('TURNOVER','ON DOWNS');
toast('DEFENSE TAKES OVER')};
setTimeout(()=>{resetFormation();
playing=true;
updateHUD()},1100)}
else if(kind==='incomplete'){down++;
toGo=toGo;
if(down>4){down=1;
toGo=10;
spot=25;
showCall('TURNOVER','ON DOWNS')}else showCall('INCOMPLETE','');
setTimeout(()=>{resetFormation();
playing=true;
updateHUD()},950)}
else if(kind==='intercept'){score[1]+=7;
showCall('PICKED OFF','');
toast('TURNOVER! RIVAL TAKES IT BACK');
setTimeout(()=>{spot=25;
down=1;
toGo=10;
resetFormation();
playing=true;
updateHUD()},1200)}
updateHUD()}

function pass(){if(!playing||passObj||carrier.y<5)return;
const rec=players.filter(p=>p.team===0&&p!==carrier&&p.route).sort((a,b)=>Math.abs(a.x-carrier.x)+Math.abs(a.y-carrier.y)-Math.abs(b.x-carrier.x)-Math.abs(b.y-carrier.y))[playNum%4];
if(!rec)return;
passObj={x:carrier.x,y:carrier.y,t:0,from:{x:carrier.x,y:carrier.y},to:rec};
carrier.carrier=false;
toast('PASS IN THE AIR');
}

function animatePass(dt){if(!passObj)return;
passObj.t+=dt*1.18;
const t=clamp(passObj.t,0,1),r=passObj.to;
passObj.x=passObj.from.x+(r.x-passObj.from.x)*t;
passObj.y=passObj.from.y+(r.y-passObj.from.y)*t;
if(t>=1){const defender=players.filter(p=>p.team===1).some(p=>Math.hypot(p.x-r.x,p.y-r.y)<9);
if(defender&&Math.random()<.2){passObj=null;
endPlay('intercept');
return}if(Math.random()<.13){passObj=null;
endPlay('incomplete');
return}carrier=r;
carrier.carrier=true;
carrier.route=null;
ball={x:r.x,y:r.y};
passObj=null;
toast('COMPLETE! KEEP MOVING');
}}

function update(dt,time){if(!playing)return;
clock-=dt*.42;
if(clock<=0){clock=0;
if(quarter<4){quarter++;
clock=240;
showCall(`${['','SECOND','THIRD','FOURTH'][quarter-1]} QUARTER`)}else{playing=false;
$('#mobileControls').style.display='none';
$('#finalTitle').textContent=score[0]>=score[1]?'VICTORY':'FINAL';
$('#finalScore').textContent=`${teams[home][0]} ${score[0]} — ${score[1]} ${teams[away][0]}`;
$('#gameover').classList.add('show')}}
if(callTimer>0){callTimer-=dt;
if(callTimer<=0)$('#callout').style.display='none'}
if(passObj){animatePass(dt);
for(const p of players.filter(p=>p.team===0&&p!==carrier&&p.route)){p.y-=dt*7;
p.x+=p.route==='left'?-dt*2:dt*2}updateHUD();
return}
if(!carrier||!carrier.carrier)return;
let dx=0,dy=0;
if(keys.ArrowUp||keys.KeyW)dy-=1;
if(keys.ArrowDown||keys.KeyS)dy+=1;
if(keys.ArrowLeft||keys.KeyA)dx-=1;
if(keys.ArrowRight||keys.KeyD)dx+=1;
const speed=(keys.ShiftLeft||keys.ShiftRight?23:15)*dt;
if(dx||dy){let l=Math.hypot(dx,dy);
carrier.x+=dx/l*speed;
carrier.y+=dy/l*speed;
carrier.angle=Math.atan2(dx,-dy)*.17;
playNum++;
}
carrier.x=clamp(carrier.x,5,95);
carrier.y=clamp(carrier.y,5,93);
ball={x:carrier.x,y:carrier.y};

// blockers engage closest defender
for(const p of players.filter(p=>p.team===0&&p!==carrier&&!p.route)){const d=players.filter(x=>x.team===1).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];
if(d&&Math.hypot(d.x-p.x,d.y-p.y)<15){d.x+=(p.x-d.x)*dt*.48;
d.y+=(p.y-d.y)*dt*.48}}
// route movement
for(const p of players.filter(p=>p.team===0&&p!==carrier&&p.route)){if(p.route==='left'){p.x-=dt*2.7;
p.y-=dt*6}else if(p.route==='right'){p.x+=dt*2.7;
p.y-=dt*6}else {p.y-=dt*2};
p.x=clamp(p.x,4,96)}
const defenders=players.filter(p=>p.team===1);
for(const d of defenders){const speedD=9.7;
let tx=carrier.x,ty=carrier.y;
if(Math.abs(d.x-carrier.x)>25&&d.y<carrier.y-17){tx=carrier.x+(carrier.x-d.x)*.18;
ty=carrier.y-3}let vx=tx-d.x,vy=ty-d.y,l=Math.hypot(vx,vy)||1;
d.x+=vx/l*speedD*dt;
d.y+=vy/l*speedD*dt;
d.angle=Math.atan2(vx,-vy)*.12;
if(Math.hypot(d.x-carrier.x,d.y-carrier.y)<5.4){endPlay('tackle');
break}}
if(carrier.y<7){endPlay('td');
return}if(carrier.y>98||carrier.x<2||carrier.x>98)endPlay('tackle');
updateHUD();
}

function frame(t){let now=t/1000,dt=Math.min(.04,now-last||0);
last=now;
update(dt,now);
draw(now);
requestAnimationFrame(frame)}requestAnimationFrame(frame);


function keydown(e){const key=e.code;
keys[key]=true;
if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(key))e.preventDefault();
if(key==='KeyQ'||key==='Space')pass()}
window.addEventListener('keydown',keydown);
window.addEventListener('keyup',e=>keys[e.code]=false);
document.querySelectorAll('[data-key]').forEach(b=>{const key=b.dataset.key;
b.addEventListener('pointerdown',e=>{e.preventDefault();
b.setPointerCapture(e.pointerId);
keys[key]=true;
if(key==='KeyQ')pass()});
['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys[key]=false))});

